//! Classification of "junk": files an expert would consider safe (or
//! reasonably safe) to reclaim without losing user data.
//!
//! Rules are matched against the lowercased absolute path with `\`
//! separators, and are intentionally narrow: anything that can hold user
//! documents, installers the user still wants, or system state needed for
//! boot/repair is *not* listed. Everything here is either regenerated by
//! Windows/the app that owns it, or is content the user already discarded
//! (Recycle Bin).
//!
//! Each rule carries:
//!   * `id`      stable identifier
//!   * `label`   short human label shown as a badge in the UI
//!   `category`  Safe  -> preselected, no user data possible
//!               Optional -> reversible-but-consequential (re-download /
//!                           rebuild cost, or no rollback after it)
//!   `min_age_minutes` how old a file must be before we offer it. Files
//!                     younger than this are likely still in use by a running
//!                     process, so deleting them just produces errors.

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Category {
    Safe,
    Optional,
}

#[derive(Clone, Copy)]
pub struct Rule {
    pub id: &'static str,
    pub label: &'static str,
    pub category: Category,
    pub min_age_minutes: u64,
}

impl Rule {
    pub fn category_str(&self) -> &'static str {
        match self.category {
            Category::Safe => "safe",
            Category::Optional => "optional",
        }
    }
}

#[derive(Clone, serde::Serialize)]
pub struct JunkHit {
    pub size: u64,
    pub path: String,
    pub mtime_ms: u64,
    pub rule: &'static str,
    pub label: &'static str,
    pub category: &'static str,
}

/// Returns the rule id for a path, or None when the file is not junk.
///
/// `p` must be the lowercased path with `\` separators (see `classify`).
fn rule_for(p: &str) -> Option<&'static Rule> {
    // Windows Temp / user temp / app temp caches: pure scratch space.
    const WINDOWS_TEMP: Rule = Rule { id: "win-temp", label: "Windows Temp", category: Category::Safe, min_age_minutes: 60 };
    const USER_TEMP: Rule = Rule { id: "user-temp", label: "Temporary files", category: Category::Safe, min_age_minutes: 60 };
    const PKG_TEMP: Rule = Rule { id: "pkg-temp", label: "App temp state", category: Category::Safe, min_age_minutes: 60 };
    const INET_CACHE: Rule = Rule { id: "inetcache", label: "Internet cache", category: Category::Safe, min_age_minutes: 30 };
    const THUMB_CACHE: Rule = Rule { id: "thumbs", label: "Thumbnail cache", category: Category::Safe, min_age_minutes: 30 };
    const BROWSER_CACHE: Rule = Rule { id: "browser-cache", label: "Browser cache", category: Category::Safe, min_age_minutes: 30 };
    const UPDATE_CACHE: Rule = Rule { id: "win-update-cache", label: "Windows Update cache", category: Category::Safe, min_age_minutes: 15 };
    const DELIVERY: Rule = Rule { id: "delivery-opt", label: "Delivery Optimization cache", category: Category::Safe, min_age_minutes: 15 };
    const RECYCLE: Rule = Rule { id: "recycle-bin", label: "Recycle Bin", category: Category::Safe, min_age_minutes: 0 };
    const CRASH: Rule = Rule { id: "crash-dumps", label: "Crash dumps", category: Category::Safe, min_age_minutes: 0 };
    const LOGS: Rule = Rule { id: "win-logs", label: "Windows logs", category: Category::Safe, min_age_minutes: 0 };
    const SYSTEM_TEMP: Rule = Rule { id: "system-temp", label: "System temp", category: Category::Safe, min_age_minutes: 60 };
    const SHADER_CACHE: Rule = Rule { id: "shader-cache", label: "GPU shader cache", category: Category::Safe, min_age_minutes: 30 };
    const SERVICING: Rule = Rule { id: "servicing-cache", label: "Servicing cache", category: Category::Safe, min_age_minutes: 60 };
    const OS_CACHE: Rule = Rule { id: "os-cache", label: "System cache", category: Category::Safe, min_age_minutes: 30 };
    const DRIVER_PKG: Rule = Rule { id: "gpu-installer", label: "GPU installer leftovers", category: Category::Safe, min_age_minutes: 0 };

    // Things that are rebuilt or re-downloadable, but whose loss has a real
    // (if small) cost: first-launch slowness, re-downloading, or the loss of
    // the ability to roll back / repair an installation.
    const PREFETCH: Rule = Rule { id: "prefetch", label: "Prefetch data", category: Category::Optional, min_age_minutes: 0 };
    const OLD_WINDOWS: Rule = Rule { id: "windows-old", label: "Previous Windows install", category: Category::Optional, min_age_minutes: 0 };
    const PKG_CACHE: Rule = Rule { id: "package-cache", label: "Installer package cache", category: Category::Optional, min_age_minutes: 0 };
    const PANTHER: Rule = Rule { id: "panther", label: "Setup logs", category: Category::Optional, min_age_minutes: 0 };
    const WER: Rule = Rule { id: "wer", label: "Crash reports", category: Category::Optional, min_age_minutes: 0 };
    const PATCH_CACHE: Rule = Rule { id: "patch-cache", label: "Update patch cache", category: Category::Optional, min_age_minutes: 0 };
    const DEV_CACHE: Rule = Rule { id: "dev-cache", label: "Dev package cache", category: Category::Optional, min_age_minutes: 0 };

    if p.contains("\\windows\\temp\\") {
        return Some(&WINDOWS_TEMP);
    }
    if p.contains("\\windows\\systemtemp\\") {
        return Some(&SYSTEM_TEMP);
    }
    if p.contains("\\appdata\\local\\temp\\") {
        return Some(&USER_TEMP);
    }
    if p.contains("\\appdata\\local\\packages\\")
        && (p.contains("\\tempstate\\") || p.contains("\\ac\\temp\\"))
    {
        return Some(&PKG_TEMP);
    }
    if p.contains("\\appdata\\local\\microsoft\\windows\\inetcache\\") {
        return Some(&INET_CACHE);
    }
    if p.contains("\\explorer\\thumbcache_")
        || p.contains("\\explorer\\iconcache_")
        || p.contains("\\microsoft\\windows\\explorer\\") && p.contains("_idx.db")
    {
        return Some(&THUMB_CACHE);
    }
    if (p.contains("\\appdata\\local\\google\\chrome\\")
        || p.contains("\\appdata\\local\\microsoft\\edge\\")
        || p.contains("\\appdata\\local\\bravesoftware\\")
        || p.contains("\\appdata\\local\\mozilla\\")
        || p.contains("\\appdata\\local\\vivaldi\\")
        || p.contains("\\appdata\\local\\opera\\"))
        && (p.contains("\\cache\\")
            || p.contains("\\cache2\\")
            || p.contains("\\code cache\\")
            || p.contains("\\gpucache\\")
            || p.contains("\\shadercache\\")
            || p.contains("\\cachestorage\\")
            || p.contains("\\dawncache\\")
            || p.contains("\\dawnwebgpucache\\")
            || p.contains("\\graphitecache\\")
            || p.contains("\\application cache\\"))
    {
        return Some(&BROWSER_CACHE);
    }
    if p.contains("\\appdata\\local\\d3dscache\\")
        || p.contains("\\appdata\\local\\microsoft\\directx shader cache\\")
        || p.contains("\\appdata\\local\\nvidia\\dxcache\\")
        || p.contains("\\appdata\\local\\nvidia\\glcache\\")
        || p.contains("\\appdata\\local\\nvidia\\nv_cache\\")
        || p.contains("\\appdata\\local\\nvidia\\computecache\\")
        || p.contains("\\appdata\\local\\amd\\dxcache\\")
        || p.contains("\\appdata\\local\\amd\\d3dcache\\")
        || p.contains("\\appdata\\local\\amd\\glcache\\")
    {
        return Some(&SHADER_CACHE);
    }
    if p.contains("\\windows\\softwaredistribution\\download\\") {
        return Some(&UPDATE_CACHE);
    }
    if p.contains("\\windows\\servicing\\lcu\\") || p.contains("\\windows\\winsxs\\temp\\") {
        return Some(&SERVICING);
    }
    if p.contains("\\programdata\\microsoft\\windows\\caches\\") {
        return Some(&OS_CACHE);
    }
    if p.contains("\\deliveryoptimization\\") {
        return Some(&DELIVERY);
    }
    if p.contains("\\$recycle.bin\\") {
        return Some(&RECYCLE);
    }
    if p.contains("\\appdata\\local\\crashdumps\\")
        || p.contains("\\windows\\minidump\\")
        || p.contains("\\windows\\livekernelreports\\")
        || p.ends_with("\\windows\\memory.dmp")
    {
        return Some(&CRASH);
    }
    if p.contains("\\windows\\logs\\")
        || p.contains("\\windows\\debug\\")
        || p.contains("\\windows\\system32\\logfiles\\")
        || p.contains("\\perflogs\\")
    {
        return Some(&LOGS);
    }
    if p.contains("\\programdata\\nvidia corporation\\downloader\\")
        || p.contains("\\programdata\\nvidia corporation\\nv_cache\\")
        || p.contains("\\programdata\\amd\\")
    {
        return Some(&DRIVER_PKG);
    }
    if p.contains("\\windows\\prefetch\\") {
        return Some(&PREFETCH);
    }
    if p.contains("\\windows.old\\")
        || p.contains("\\$windows.~bt\\")
        || p.contains("\\$windows.~ws\\")
    {
        return Some(&OLD_WINDOWS);
    }
    if p.contains("\\programdata\\package cache\\") {
        return Some(&PKG_CACHE);
    }
    if p.contains("\\windows\\panther\\") {
        return Some(&PANTHER);
    }
    if p.contains("\\appdata\\local\\microsoft\\windows\\wer\\")
        || p.contains("\\programdata\\microsoft\\windows\\wer\\")
    {
        return Some(&WER);
    }
    if p.contains("\\windows\\installer\\$patchcache$\\") {
        return Some(&PATCH_CACHE);
    }
    if p.contains("\\appdata\\local\\npm-cache\\")
        || p.contains("\\appdata\\roaming\\npm-cache\\")
        || p.contains("\\appdata\\local\\pip\\cache\\")
        || p.contains("\\appdata\\local\\yarn\\cache\\")
        || p.contains("\\appdata\\local\\pnpm-store\\")
        || p.contains("\\appdata\\local\\bun\\install\\cache\\")
        || p.contains("\\.nuget\\packages\\")
        || p.contains("\\.gradle\\caches\\")
        || p.contains("\\.m2\\repository\\")
        || p.contains("\\.cargo\\registry\\cache\\")
        || p.contains("\\.cargo\\git\\")
        || p.contains("\\go\\pkg\\mod\\cache\\")
    {
        return Some(&DEV_CACHE);
    }
    None
}

/// Never touch these, whatever a rule says: they are live system state and
/// deleting them breaks the machine (paging/hibernation, boot, the registry,
/// per-user registry hives, or the volume's own metadata).
fn is_protected(p: &str) -> bool {
    let name = p.rsplit('\\').next().unwrap_or("");
    if name.is_empty() {
        return true;
    }
    matches!(
        name,
        "pagefile.sys" | "swapfile.sys" | "hiberfil.sys" | "bootmgr" | "bootnxt" | "bootstat.dat"
    ) || p.ends_with("\\boot\\bcd")
        || p.contains("\\system volume information\\")
        || p.contains("\\$mft")
}

/// Classifies a file. `path` must be a normal (non-verbatim) path.
/// Returns the matching rule, already age-filtered: files touched within the
/// rule's `min_age_minutes` window are likely still in use, so they are not
/// offered for deletion.
pub fn classify(path: &str, mtime_ms: u64, now_ms: u64) -> Option<&'static Rule> {
    let lower = path.replace('/', "\\").to_lowercase();
    if is_ignored_name(&lower) || is_protected(&lower) {
        return None;
    }
    let rule = rule_for(&lower)?;
    if rule.min_age_minutes > 0 && mtime_ms != 0 {
        let age_ms = now_ms.saturating_sub(mtime_ms);
        if age_ms < rule.min_age_minutes * 60_000 {
            return None;
        }
    }
    Some(rule)
}

/// A few names that must never be treated as junk even inside junk folders:
/// folder metadata and the current user's own markers.
pub fn is_ignored_name(lower_path: &str) -> bool {
    let name = lower_path.rsplit('\\').next().unwrap_or("");
    matches!(name, "desktop.ini" | "thumbs.db" | "iconcache.db" | ".gitkeep")
}

pub fn now_ms() -> u64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}
